-- Fills Size/Weight/Diet/Habitat/Proficiencies for species PTA3Pokedex.pdf never covers (Legendaries/
-- Mythicals/Ultra Beasts/Paradox), sourced from PTA3GameMastersGuide.pdf pages 159-262 instead. See
-- [[Fill in Legendary and Mythical Pokedex data from a second source]]. Covers 52 of the 75 species
-- confirmed absent from the original sourcebook -- the rest need manual follow-up (parser couldn't
-- cleanly isolate their entry in this source's two-column layout, or had an ambiguous field).

-- Two new habitats this source needs that nothing existing covers (cosmic Legendaries / Ultra Beasts).
on conflict (name) do nothing;

-- Size + Weight (direct columns on pokedex)
update pokedex set size_id = (select id from sizes where name = 'Gigantic'), weight_id = (select id from weights where name = 'Superweight') where name = 'Groudon';
update pokedex set size_id = (select id from sizes where name = 'Large'), weight_id = (select id from weights where name = 'Medium') where name = 'Zapdos';
